    @Test
    void filterInTheUrlIsAppliedAndShown() {
        open("/?name=vir&status=ACTIVE,CLOSED");

        assertThat(summary()).hasText("Showing 10 of 500");
        assertThat(nameInput()).hasValue("vir");
        assertThat(page.locator("#status-filter")).containsText("ACTIVE");
        assertThat(page.locator("#status-filter")).containsText("CLOSED");
    }

    @Test
    void typingNarrowsTheListAndCostsOneRoundOfQueries() {
        open("/?status=ACTIVE,CLOSED");
        assertThat(summary()).hasText("Showing 333 of 500");
        queryLog.clear();

        nameInput().pressSequentially("virtanen", new Locator.PressSequentiallyOptions().setDelay(60));

        // No Enter, no blur: the grid follows the typing.
        assertThat(summary()).hasText("Showing 10 of 500");
        assertEquals("Virtanen", firstRowLastName());

        int queries = queryLog.countQueries().size() + queryLog.pageQueries().size();
        assertTrue(queries <= 2,
                "typing eight letters cost " + queries + " queries: counts="
                        + queryLog.countQueries() + " pages=" + queryLog.pageQueries());
    }

    @Test
    void theFilterEndsUpInTheAddressBar() {
        open("/?status=ACTIVE,CLOSED");

        nameInput().fill("vir");
        assertThat(summary()).hasText("Showing 10 of 500");
        assertEquals(baseUrl() + "/?name=vir&status=ACTIVE,CLOSED", page.url());

        nameInput().fill("");
        assertThat(summary()).hasText("Showing 333 of 500");
        assertEquals(baseUrl() + "/?status=ACTIVE,CLOSED", page.url());
    }

