+/**
+ * What the customer list is narrowed down to: a free-text name filter and a set
+ * of statuses. Both parts are optional, and an {@link #EMPTY} filter matches
+ * every customer.
+ *
+ * <p>The filter is a value: it is passed to {@link CustomerRepository}, which
+ * applies it while paging and counting, so the UI never has to hold the whole
+ * data set.
+ *
+ * @param name     free text; split on whitespace into terms, each of which must
+ *                 occur in the first or the last name. Leading, trailing and
+ *                 repeated whitespace is not significant, and matching ignores
+ *                 case and accents in both directions.
+ * @param statuses the statuses to show; empty means every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+
+    /** Matches every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = (name == null) ? "" : WHITESPACE.matcher(name.trim()).replaceAll(" ");
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                // An EnumSet iterates in declaration order, which is the order the
+                // statuses appear in the URL.
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    public static CustomerFilter of(String name, Collection<CustomerStatus> statuses) {
+        return new CustomerFilter(name, statuses == null ? Set.of() : Set.copyOf(statuses));
+    }
+
+    /** Returns {@code filter}, or {@link #EMPTY} if it is {@code null}. */
+    public static CustomerFilter orEmpty(CustomerFilter filter) {
+        return (filter == null) ? EMPTY : filter;
+    }
+
+    /** True when this filter matches every customer. */
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /** The name filter split into the terms that all have to match. */
+    public List<String> terms() {
+        return name.isEmpty() ? List.of() : List.of(WHITESPACE.split(fold(name)));
+    }
+
+    /**
+     * Compiles this filter once into a predicate, so that the terms are folded
+     * once per query rather than once per row.
+     */
+    public Predicate<Customer> asPredicate() {
+        List<String> terms = terms();
+        Set<CustomerStatus> allowed = statuses;
+        return customer -> (allowed.isEmpty() || allowed.contains(customer.status()))
+                && matchesName(customer, terms);
+    }
+
+    /** True when {@code customer} satisfies both halves of this filter. */
+    public boolean matches(Customer customer) {
+        return asPredicate().test(customer);
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        for (String term : terms) {
+            if (!firstName.contains(term) && !lastName.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /**
+     * Folds text down to a form that compares case- and accent-insensitively, so
+     * that {@code makinen}, {@code MAKINEN} and {@code mäkinen} all fold to the
+     * same thing as {@code Mäkinen}.
+     */
+    public static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        String stripped = DIACRITICS.matcher(decomposed).replaceAll("");
+        return expandUndecomposedLetters(stripped).toLowerCase(Locale.ROOT);
+    }
+
+    /**
+     * Letters that carry their mark inside the glyph, so NFD leaves them alone.
+     */
+    private static String expandUndecomposedLetters(String text) {
+        StringBuilder result = new StringBuilder(text.length());
+        for (int i = 0; i < text.length(); i++) {
+            char c = text.charAt(i);
+            switch (c) {
+                case 'ø', 'Ø' -> result.append('o');
+                case 'æ', 'Æ' -> result.append("ae");
+                case 'œ', 'Œ' -> result.append("oe");
+                case 'ß' -> result.append("ss");
+                case 'đ', 'Đ', 'ð', 'Ð' -> result.append('d');
+                case 'þ', 'Þ' -> result.append("th");
+                case 'ł', 'Ł' -> result.append('l');
+                case 'ħ', 'Ħ' -> result.append('h');
+                case 'ı' -> result.append('i');
+                default -> result.append(c);
+            }
+        }
+        return result.toString();
+    }
+}
