+        applyFilter(CustomerFilter.of(nameFilter.getValue(), statusFilter.getValue()), true);
+    }
+
+    private void applyFilter(CustomerFilter newFilter, boolean writeToUrl) {
+        boolean changed = !newFilter.equals(filter);
+        filter = newFilter;
+        if (changed) {
+            // Re-queries the backend: one count, then the page the user is looking
+            // at. The grid still holds nothing but that page.
+            grid.getDataProvider().refreshAll();
+            countMatching();
+        }
+        if (writeToUrl) {
+            writeFilterToUrl();
+        }
+    }
+
+    /**
+     * Asks the backend how many customers match, and says so. The grid is about
+     * to ask the same question, so the answer is kept for it.
+     */
+    private int countMatching() {
+        matchingCount = customerService.count(filter);
+        countedFilter = filter;
+        showSummary(matchingCount);
+        return matchingCount;
+    }
+
+    /**
+     * The row count for the grid. A count just made for this very filter is
+     * handed over once rather than asked for twice; anything else is a fresh
+     * count query.
+     */
+    private int countForGrid(Query<Customer, Void> query) {
+        if (filter.equals(countedFilter)) {
+            countedFilter = null;
+            return matchingCount;
+        }
+        return countMatching();
+    }
+
+    private void showSummary(int matching) {
+        summary.setText("Showing " + matching + " of " + totalCount);
+    }
+
+    /**
+     * Puts the current filter in the address bar, replacing the current history
+     * entry rather than adding one, so that typing leaves no trail to walk back
+     * through.
+     */
+    private void writeFilterToUrl() {
+        getUI().ifPresent(ui -> ui.getPage().executeJs(REPLACE_URL, queryString()));
+    }
+
+    /** The current filter as a query string, {@code ""} when nothing is filtered. */
+    public String queryString() {
+        StringBuilder query = new StringBuilder();
+        if (!filter.name().isEmpty()) {
+            query.append(NAME_PARAMETER).append('=').append(encode(filter.name()));
+        }
+        if (!filter.statuses().isEmpty()) {
+            if (!query.isEmpty()) {
+                query.append('&');
+            }
+            query.append(STATUS_PARAMETER).append('=').append(joinStatuses(filter.statuses()));
+        }
+        return query.isEmpty() ? "" : "?" + query;
+    }
+
+    private static String joinStatuses(Set<CustomerStatus> statuses) {
+        return statuses.stream().map(CustomerStatus::name).collect(Collectors.joining(","));
+    }
+
+    private static String encode(String value) {
+        return URLEncoder.encode(value, StandardCharsets.UTF_8).replace("+", "%20");
+    }
+
+    private static String firstParameter(QueryParameters parameters, String name) {
+        List<String> values = parameters.getParameters(name);
+        return values.isEmpty() ? "" : values.get(0);
+    }
+
+    /**
+     * Reads {@code status=ACTIVE,CLOSED}, and also tolerates the same parameter
+     * repeated. Anything that is not a status name is ignored.
+     */
+    private static Set<CustomerStatus> parseStatuses(List<String> values) {
+        Set<CustomerStatus> statuses = EnumSet.noneOf(CustomerStatus.class);
+        for (String value : values) {
+            for (String name : value.split(",")) {
+                String trimmed = name.trim().toUpperCase(Locale.ROOT);
+                if (trimmed.isEmpty()) {
+                    continue;
+                }
+                for (CustomerStatus status : CustomerStatus.values()) {
+                    if (status.name().equals(trimmed)) {
+                        statuses.add(status);
+                    }
+                }
+            }
+        }
+        return statuses;
     }

